// Keep Tab cycling within the visible dialog controls, including confirmation mode.
for (const dialog of ["'$('"'#editor'), "'$('"'#details')]) dialog.addEventListener('keydown', e => {
 if (e.key "'!== '"'Tab') return;
 const controls = [...dialog.querySelectorAll('button, input, textarea, select, a[href], [tabindex=\"0\"]')].filter(el => "'!el.disabled && el.getClientRects().length);
 const first = controls[0], last = controls.at(-1);
 if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }
 else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }
});
